def walk(path, acc):
    for name in repo.list(path):
        p = path + "/" + name if path != "." else name
        if name.endswith("/"):
            walk(p.rstrip("/"), acc)
        else:
            acc.append(p)
    return acc

all_files = []
walk(".", all_files)
contents = {}
for p in all_files:
    if p.startswith("target/"):
        continue
    contents[p] = repo.read(p, missing_ok=True)
result({"all_files": all_files, "contents": contents})

